// Virtuoso Opera Violin - Visual Stage Pass
// Synchronized with the 144 BPM Presto tempo
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.y, iResolution.x);

    // Dramatic opera stage background glow
    float dist = length(uv);
    vec3 bg = mix(vec3(0.06, 0.02, 0.04), vec3(0.01, 0.005, 0.02), dist);

    // Fast 144 BPM Presto tempo: 16th-note pulse
    float beat = iTime * (144.0 / 60.0);
    float sixteenth = beat * 4.0;
    float pulse = exp(-6.0 * fract(sixteenth));
    float beatPulse = exp(-4.0 * fract(beat));

    // 4 Glowing golden violin strings vibrating to Vivaldi's rhythm
    vec3 col = bg;
    float stringPositions[4] = float[4](-0.24, -0.08, 0.08, 0.24);
    vec3 stringColors[4] = vec3[4](
        vec3(0.9, 0.45, 0.15),
        vec3(1.0, 0.70, 0.25),
        vec3(1.0, 0.85, 0.40),
        vec3(0.95, 0.95, 0.80)
    );

    for (int i = 0; i < 4; i++) {
        float y0 = stringPositions[i];
        float freq = float(i + 1) * 32.0;
        float amp = (0.012 + 0.018 * pulse) * sin(iTime * 25.0 + float(i) * 2.0);
        float wave = sin(uv.x * freq + iTime * 15.0) * amp * (1.0 - uv.x * uv.x * 2.5);

        float d = abs(uv.y - y0 - wave);
        float glow = 0.0035 / (d + 0.001);
        col += stringColors[i] * glow;
    }

    // Concentric acoustic sound ripples pulsating to the bass downbeat
    float ripple = sin(dist * 35.0 - iTime * 10.0);
    col += vec3(0.5, 0.2, 0.6) * smoothstep(0.7, 1.0, ripple) * 0.20 * beatPulse * exp(-dist * 1.8);

    // Subtle vignette
    col *= 1.0 - 0.4 * dist * dist;

    fragColor = vec4(col, 1.0);
}

// Vivaldi "Summer" (L'Estate - Presto) in G Minor
// Procedural Orchestral Violin & Baroque Basso Continuo in GLSL
// Clean additive string synthesis with note-relative phase (zero clicks/noise)

float midiToFreq(float note) {
    return 440.0 * exp2((note - 69.0) / 12.0);
}

// Pure violin tone with harmonic series and wood cavity resonance
float violinVoice(float freq, float tau, float noteDur) {
    if (freq <= 0.0) return 0.0;

    // Smooth bow attack and staccato release
    float attack = smoothstep(0.0, 0.006, tau);
    float release = 1.0 - smoothstep(noteDur * 0.70, noteDur, tau);
    float env = attack * release;

    // Natural acoustic vibrato (6.2 Hz, builds slightly after attack)
    float vib = 0.008 * sin(6.2831853 * 6.2 * tau) * smoothstep(0.02, 0.07, tau);
    float f = freq * (1.0 + vib);

    // Note-local phase: tau starts at 0 at each note, ensuring 0-crossing continuity!
    float p = 6.2831853 * f * tau;

    // Additive harmonic series of bowed string (clean, no random white noise)
    float sig = sin(p)
              + 0.55 * sin(2.0 * p)
              + 0.35 * sin(3.0 * p)
              + 0.20 * sin(4.0 * p)
              + 0.12 * sin(5.0 * p)
              + 0.07 * sin(6.0 * p)
              + 0.04 * sin(7.0 * p);

    // Body resonance (formant at 2500 Hz for violin presence)
    float presence = 1.0 + 0.45 * exp(-pow((freq - 2500.0) / 1200.0, 2.0));

    // Warm saturation
    float voice = (sig * presence) / (1.0 + abs(sig) * 0.3);
    return voice * env * 0.32;
}

// Basso Continuo (Cello / Contrabass driving 8th-note pulse)
float bassVoice(float freq, float tau, float beatDur) {
    if (freq <= 0.0) return 0.0;

    // Punchy staccato bass attack with exponential decay
    float env = smoothstep(0.0, 0.004, tau) * exp(-12.0 * tau);
    float p = 6.2831853 * freq * tau;

    // Deep bass tone (fundamental + 2nd octave harmonic + warm 3rd harmonic)
    float sig = sin(p) + 0.6 * sin(2.0 * p) + 0.3 * sin(3.0 * p);
    return sig * env * 0.42;
}

// Harpsichord / Plucked chord accompaniment
float harpsichord(float freq, float tau) {
    if (freq <= 0.0) return 0.0;
    float env = exp(-22.0 * tau);
    float p = 6.2831853 * freq * tau;
    // Bright plucked string
    float sig = sin(p) + 0.7 * sin(2.0 * p) + 0.4 * sin(3.0 * p) + 0.25 * sin(4.0 * p);
    return sig * env * 0.15;
}

// 64-step fast 16th-note violin score (Vivaldi Summer - Presto in G Minor)
float getSummerViolin(int step) {
    int s = step % 64;
    // Measure 1: Gm arpeggio run (G5, D5, Bb4, G4...)
    if (s < 16) {
        int m1[16] = int[16](79, 74, 70, 67, 70, 74, 79, 74, 79, 74, 70, 67, 70, 74, 79, 74);
        return float(m1[s]);
    }
    // Measure 2: D7 dramatic tension (F#5, D5, A4, F#4...)
    else if (s < 32) {
        int m2[16] = int[16](78, 74, 69, 66, 69, 74, 78, 74, 78, 74, 69, 66, 69, 74, 78, 74);
        return float(m2[s - 16]);
    }
    // Measure 3: Cm -> Gm harmonic progression
    else if (s < 48) {
        int m3[16] = int[16](75, 72, 67, 63, 67, 72, 75, 72, 74, 70, 67, 62, 67, 70, 74, 70);
        return float(m3[s - 32]);
    }
    // Measure 4: Dramatic climax and virtuoso cadence
    else {
        int m4[16] = int[16](72, 69, 66, 62, 66, 69, 72, 69, 70, 67, 74, 70, 79, 74, 82, 79);
        return float(m4[s - 48]);
    }
}

// Basso continuo root note (8th-note pulse)
float getBassNote(int beatStep) {
    int bar = (beatStep / 8) % 4;
    // Bar 0: Gm (G2)
    // Bar 1: D7 (D2)
    // Bar 2: Cm -> Gm (C2 -> G2)
    // Bar 3: D7 -> Gm (D2 -> G2)
    if (bar == 0) return 43.0; // G2
    if (bar == 1) return 38.0; // D2
    if (bar == 2) {
        return (beatStep % 8 < 4) ? 48.0 : 43.0; // C3 -> G2
    }
    return (beatStep % 8 < 4) ? 38.0 : 43.0; // D2 -> G2
}

vec2 mainSound( int samp, float time ) {
    // 144 BPM Presto tempo: 16th-note clock
    float tempo = 144.0;
    float beatDur = 60.0 / tempo;         // ~0.4167s per quarter beat
    float noteDur16 = beatDur / 4.0;      // ~0.1042s per 16th note
    float noteDur8 = beatDur / 2.0;       // ~0.2083s per 8th note

    // 1. Fast Solo Violin
    float step16f = time / noteDur16;
    int step16 = int(floor(step16f));
    float tau16 = fract(step16f) * noteDur16;

    float vMidi = getSummerViolin(step16);
    float vFreq = midiToFreq(vMidi);
    float soloViolin = violinVoice(vFreq, tau16, noteDur16);

    // 2. Orchestral Cello / Contrabass (Driving 8th notes)
    float step8f = time / noteDur8;
    int step8 = int(floor(step8f));
    float tau8 = fract(step8f) * noteDur8;

    float bMidi = getBassNote(step8);
    float bFreq = midiToFreq(bMidi);
    float orchestraBass = bassVoice(bFreq, tau8, noteDur8);

    // 3. Harpsichord rhythmic comping on 8th-note offbeats
    float hChord = 0.0;
    if (step8 % 2 == 1) { // Offbeat rhythm
        hChord += harpsichord(midiToFreq(bMidi + 12.0), tau8);
        hChord += harpsichord(midiToFreq(bMidi + 15.0), tau8);
    }

    // Stereo stage arrangement
    // Solo Violin panned center-left, Bass centered, Harpsichord center-right
    float left = soloViolin * 0.70 + orchestraBass * 0.45 + hChord * 0.25;
    float right = soloViolin * 0.50 + orchestraBass * 0.45 + hChord * 0.45;

    // Clean output
    vec2 outAudio = vec2(left, right);
    return clamp(outAudio, -0.95, 0.95);
}
